/* Personalization fields on products that ship (round 13): one column on products, personalization, the list of what a buyer is asked when buying (a name to engrave, a message, a photo to print; up to five fields, each a label, a type of text, long text or photo, required or not, a character limit, a hint), written by the product editor's Personalization card and read by every product page (the Storelib theme's product section, the storelib.com product page, an imported theme's product.metafields.storelib.personalization). A list under 16 KB; NOT VALID, so no old row is rechecked. Buyers' photos are kept by part 308 (cart_uploads and its private bucket), so run 308 too for photo fields. Run after the products table exists. Until it runs, the editor saves products as before and leaves the fields unsaved, and no product page asks for anything. No rows change. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 307: the products table is not there yet.'; RETURN; END IF; ALTER TABLE public.products ADD COLUMN IF NOT EXISTS personalization jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_personalization_shape, ADD CONSTRAINT products_personalization_shape CHECK (jsonb_typeof(personalization) = 'array' AND jsonb_array_length(personalization) <= 5 AND pg_column_size(personalization) < 16384) NOT VALID; END $do$;
notify pgrst, 'reload schema';
